      SUBROUTINE INITZECC     INITIAL VALUES OF MATRICES AND LOGICAL VARIABLESCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'BROAD.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM0F.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM1C.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM1E.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM2D.CIN'      INCLUDE 'ELM6.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8D.CIN'      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM8L.CIN'      INCLUDE 'ELM8M.CIN'      INCLUDE 'ELM9.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM13C.CIN'      INCLUDE 'ELM14A.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM16C.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM17B.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'ELM22A.CIN'      INCLUDE 'ELM24B.CIN'      INCLUDE 'ELM26B.CIN'      INCLUDE 'ELM31A.CIN'      INCLUDE 'ELM38A.CIN'      INCLUDE 'ELM39A.CIN'      INCLUDE 'ETAP.CIN'      INCLUDE 'LXRAN.CIN'      INCLUDE 'NHORN.CIN'      INCLUDE 'OCP.CIN'      INCLUDE 'RC.CIN'      INCLUDE 'RCP.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'R0P.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'R3P.CIN'      INCLUDE 'STEPT1.CIN'      INCLUDE 'SVP.CIN'      INCLUDE 'TC.CIN'      INCLUDE 'TC2.CIN'      INCLUDE 'UC.CIN'      INCLUDE 'UC2.CIN'CC     LOCAL VARIABLESC      INTEGER  J, K, NCC------------------------------------------------------------------------      NUM = 1      IF (NV3 .GE. 1) THEN        DO 5 N = 1, NV3, 1        LCV(N) = 0.0        RVP(N) = .FALSE.        R2VP(N)= .FALSE.        SVP(N) = .FALSE.        CVP(N) = .FALSE.        OVP(N) = .FALSE.        EVP(N) = .FALSE.    5   CONTINUE      ENDIFC      DO 11 J = 1, 3      XR(J) = 0.0      XT(J) = 0.0      X0SV(J) = 0.0   11 CONTINUE      DO 12 J = 1, 3      DO 12 K = 1, 3      OR(J,K) = 0.0      OT(J,K) = 0.0      OSV(J,K) = 0.0   12 CONTINUE      DO 13 J = 1, 3   13 IVMS(J) = 0      NC = 0      NV1 = 0      NDIF = 1      NM = 0      LC = 0.0      TOTANG = 0.0      TOTROT = 0.0      TOTRA = 0.0      R0P = .FALSE.      RCP = .FALSE.      R2P  = .FALSE.      R3P = .FALSE.      RI = 0.0      DO 14 J = 1, 6   14 CO(J) = 0.0      LBEAM = .FALSE.      LTWISS = .FALSE.      SOFA = .FALSE.      RECENT = .FALSE.      PSIXO = 0.0      PSIYO = 0.0      DOPH = .TRUE.      RAY = .FALSE.      DO 16 N = 1, 10      LNMT(N) = .FALSE.   16 R2PM(N) = .FALSE.      DMC = .FALSE.      FFIN = .FALSE.      FFOUT = .FALSE.      DCOV = .FALSE.      CAP = .FALSE.      IR = 1      RORC = 0      MCFO = 0      ALO(1) = .FALSE.      ALO(2) = .FALSE.      BEFORE = .FALSE.      NOR = .FALSE.      TWP = .FALSE.      CPS = .FALSE.      CPR = .TRUE.      RAT = .FALSE.      R1P = .FALSE.      LAY = .FALSE.      SUPP = .FALSE.      ONLY = .FALSE.      TERSE = .FALSE.      LCPR = .TRUE.      REFER = .FALSE.      ACCEL = .FALSE.      UNRO = .FALSE.      ELPR = .TRUE.      ANIN = .FALSE.      NARROW = .FALSE.      PBP = .FALSE.      PRON = .NOT. LSTEP .OR. BROAD      PMK = .FALSE.      LAY191 = .FALSE.      WARN20 = .TRUE.      NPFR = 0      TYP1 = 0      MPMAD = .FALSE.      FOTILT = 0.0      SM = 0.0      PREF = 0.0      LPRF = .FALSE.      NORD1 = 1      NORD2 = 1      NORD3 = 1      NORDX = 1      LINEAR = .FALSE.      SEXLIM = .FALSE.      DO 20 N = 1, 9   20 VARS(N) = 0      DO 30 N = 1, NPVAR   30 LREG(N) = .FALSE.      IP = 0      NDLEV = 0      NULEV = 0      ATWORK = NUSE .EQ. 0      DO 41 J = 1, 4   41 PRAN2(J) = 0.0      PRAN3 = 0.0      DO 42 J = 1, 17   42 PRAN4(J) = 0.0      DO 43 J = 1, 5   43 PRAN5(J) = 0.0      DO 44 J = 1, 6   44 PRAN7(J) = 0.0      DO 45 J = 1, 4   45 PRAN11(J) = 0.0      DO 47 J = 1, 4   47 PRAN18(J) = 0.0      DO 48 J = 1, 3   48 PRAN19(J) = 0.0      PRAN20 = 0.0      DO 49 J = 1, 4   49 PRAN25(J) = 0.0      DO 50 J = 1, 23   50 PRAN28(J) = 0.0      DO 51 J = 1, 5   51 PRAN34(J) = 0.0      DO 52 J = 1, 6   52 PRAN43(J) = 0.0      BDBI = 0.0      APBI(1) = 0.0      APBI(2) = 0.0      LAYKI = 0.0      LAYLI = 0.5      LAYXI = 0.0      RAB1I = 0.0      RAB2I = 0.0      RMPSI = 0.0      VRNI = 0.0      NPNI = 0.0      BDBPI = 0.0      RNMSI = 0.0      GAMI = 0.0      MKG = .FALSE.      DRC = .FALSE.      PLOT = .FALSE.      LPLOT = .FALSE.      PLNOW = .FALSE.      LXRAN = .FALSE.      CALL RESET(2)      CALL RESET(3)      CALL RESET(4)      XINIT = 0.0      YINIT = 0.0      ZINIT = 0.0      THINIT = 0.0      PHINIT = 0.0      NHORN = 0      DO 61 J = 1, 6      DO 61 K = 1, 6      RC(J,K) = 0.0      RC2(J,K) = 0.0   61 CONTINUE      DO 62 J = 1, 6      RC(J,J) = 1.0      RC2(J,J) = 1.0   62 CONTINUE      DO 63 J = 1, 105      TCL(J) = 0.0      TC2L(J) = 0.0   63 CONTINUE      DO 64 J = 1, 280      UCL(J) = 0.0      UC2L(J) = 0.0   64 CONTINUE      CALL UNITS(0)      LIMTD = .FALSE.      CALL RANST      CALL INITB      CALL INITL      RETURN      END